function validate(input) {
  const [callCount] = input;
  if (!Number.isInteger(callCount) || callCount < 0 || callCount > 50) return 'callCount must be an integer from 0 to 50.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [callCount] = input, values = [];
  const gen = solve();
  if (!gen || typeof gen.next !== 'function') throw new Error('fibGenerator must return a generator object.');
  kit.trace('fibGenerator() creates the generator');
  for (let i = 0; i < callCount; i++) {
    const step = gen.next();
    if (!step || typeof step.value !== 'number') throw new Error('Each next() call must produce a number as its value.');
    kit.trace(`gen.next() yields ${step.value}`);
    values.push(step.value);
  }
  return values;
}

